@Override
	public void verifyComponentsAfterLoad(ItemStack pStack) {
		if(pStack.has(DataComponents.CUSTOM_DATA)) {
			CustomData patch = pStack.get(DataComponents.CUSTOM_DATA);
			if(patch == null) {
				return;
			}

			CompoundTag compound = patch.copyTag();

			ICADData data = PsiCapabilities.cadData(pStack);
			if(data != null) {
				if(compound.contains(TAG_TIME_LEGACY)) {
					data.setTime(compound.getInt(TAG_TIME_LEGACY));
					compound.remove(TAG_TIME_LEGACY);
				}

				if(compound.contains(TAG_STORED_PSI_LEGACY)) {
					data.setBattery(compound.getInt(TAG_STORED_PSI_LEGACY));
					compound.remove(TAG_STORED_PSI_LEGACY);
				}

				HashSet<String> keys = new HashSet<>(compound.getAllKeys());

				for(String key : keys) {
					Matcher matcher = VECTOR_PREFIX_PATTERN.matcher(key);
					if(matcher.find()) {
						CompoundTag vec = compound.getCompound(key);
						compound.remove(key);
						int memory = Integer.parseInt(matcher.group(1));
						Vector3 vector = new Vector3(vec.getDouble(TAG_X_LEGACY),
								vec.getDouble(TAG_Y_LEGACY),
								vec.getDouble(TAG_Z_LEGACY));
						data.setSavedVector(memory, vector);
					}
				}

				if(compound.contains("CapabilityData")) {
					CompoundTag capability = compound.getCompound("CapabilityData");
					compound.remove("CapabilityData");

					if(capability.contains("Time")) {
						data.setTime(capability.getInt("Time"));
					}

					if(capability.contains("Battery")) {
						data.setBattery(capability.getInt("Battery"));
					}

					if(capability.contains("Memory")) {
						ListTag memory = capability.getList("Memory", Tag.TAG_LIST);
						for(int i = 0; i < memory.size(); i++) {
							ListTag vec = (ListTag) memory.get(i);
							if(vec.getElementType() == Tag.TAG_DOUBLE && vec.size() >= 3) {
								data.setSavedVector(i, new Vector3(vec.getDouble(0), vec.getDouble(1), vec.getDouble(2)));
							}
						}
					}
				}
			}

			ISocketable sockets = getSocketable(pStack);
			RegistryAccess registries = RegistryAccess.fromRegistryOfRegistries(BuiltInRegistries.REGISTRY);
			if(sockets != null) {
				for(EnumCADComponent components : EnumCADComponent.values()) {
					if(compound.contains("component" + components.name())) {
						ItemStack component = LegacyItemStacks.parse(registries, compound.getCompound("component" + components.name()));
						ItemCAD.setComponent(registries, pStack, component);
						compound.remove("component" + components.name());
					}
				}
				for(int i = 0; i < ISocketable.MAX_ASSEMBLER_SLOTS; i++) {
					if(compound.contains("bullet" + i)) {
						ItemStack bullet = LegacyItemStacks.parse(registries, compound.getCompound("bullet" + i));
						sockets.setBulletInSocket(i, bullet);
						compound.remove("bullet" + i);
					}
				}
				if(compound.contains("selectedSlot")) {
					sockets.setSelectedSlot(compound.getInt("selectedSlot"));
					compound.remove("selectedSlot");
				}
			}
			CustomData.set(DataComponents.CUSTOM_DATA, pStack, compound);
		}
	}

public static ItemStack parse(HolderLookup.Provider provider, CompoundTag compound) {
		ItemStack stack = ItemStack.parseOptional(provider, compound);
		if(stack.isEmpty()) {
			return stack;
		}

		if(compound.contains("Count", Tag.TAG_ANY_NUMERIC)) {
			stack.setCount(compound.getInt("Count"));
		}
		if(compound.contains("tag", Tag.TAG_COMPOUND)) {
			stack.applyComponents(DataComponentPatch.builder()
					.set(DataComponents.CUSTOM_DATA, CustomData.of(compound.getCompound("tag")))
					.build());
		}
		return stack;
	}

@Override
  public void loadAdditional(CompoundTag tag, HolderLookup.Provider registries) {
    filter.deserializeNBT(registries,tag.getCompound("filter"));
    this.radius = tag.getInt("radius");
    entityFilter = EntityFilterType.values()[tag.getInt("entityFilter")];
    if (tag.contains(NBTENERGY)) {
      energy.deserializeNBT(registries, tag.get(NBTENERGY));
    }
    inventory.deserializeNBT(registries,tag.getCompound(NBTINV));
  if (tag.contains("Effects", 9)) {
      ListTag listnbt = tag.getList("Effects", 10);
      this.effects.clear();
      for (int i = 0; i < listnbt.size(); ++i) {
        MobEffectInstance effectinstance = MobEffectInstance.load(listnbt.getCompound(i));
        if (effectinstance != null) {
          effects.add(effectinstance);
        }
      }
    }

    super.loadAdditional(tag, registries);
  }

@Override
    protected void loadAdditional(CompoundTag tag, HolderLookup.Provider pRegistries) {
        super.loadAdditional(tag, pRegistries);
        String ritualIDString = tag.getString("ritualID");
        if (!ritualIDString.isEmpty()) {
            ResourceLocation ritualID = ResourceLocation.tryParse(ritualIDString);
            ritual = RitualRegistry.getRitual(ritualID);
            if (ritual != null) {
                ritual.tile = this;
                ritual.read(pRegistries, tag);
            }
        } else {
            ritual = null;
        }
        color = ParticleColorRegistry.from(tag.getCompound("color"));
        isDecorative = tag.getBoolean("decorative");
        isOff = tag.getBoolean("off");

        if (tag.contains("relayPos")) {
            this.relayPos = BlockPos.of(tag.getLong("relayPos"));
        }
    }

@Override
	public void verifyComponentsAfterLoad(ItemStack pStack) {
		if(pStack.has(DataComponents.CUSTOM_DATA)) {
			CustomData patch = pStack.get(DataComponents.CUSTOM_DATA);
			if(patch == null) {
				return;
			}

			CompoundTag compound = patch.copyTag();

			if(compound.contains("spell")) {
				pStack.set(DataComponents.RARITY, Rarity.RARE);
				Spell spell = Spell.createFromNBT(compound.getCompound("spell"));
				pStack.set(ModDataComponents.SPELL.get(), spell);
				compound.remove("spell");
			} else {
				pStack.set(DataComponents.RARITY, Rarity.COMMON);
			}
			CustomData.set(DataComponents.CUSTOM_DATA, pStack, compound);
		}
	}

